G=[[8]*w for _ in range(h)]
pat=[[None,None,None,1,7],[None,1,0,0,1],[7,0,1,1,7]]
# original source centered at (3,10)
centers=[(3,10),(2,4),(7,3),(9,8),(11,2),(16,3),(16,9)]
